#include <DHT.h>
// Library Manager: search "DHT sensor library" by Adafruit

#define DHT_PIN  4
#define DHT_TYPE DHT22
DHT dht(DHT_PIN, DHT_TYPE);

unsigned long lastRead = 0;

void setup() {
  Serial.begin(115200);
  dht.begin();
  Serial.println(F("DHT22 ready"));
}

void loop() {
  if (millis() - lastRead >= 2000) {  // 2s minimum interval
    lastRead = millis();

    float humidity    = dht.readHumidity();
    float temperature = dht.readTemperature();  // Celsius
    float tempF       = dht.readTemperature(true); // Fahrenheit
    float heatIndex   = dht.computeHeatIndex(temperature, humidity, false);

    if (isnan(humidity) || isnan(temperature)) {
      Serial.println(F("Error: Failed to read DHT22"));
      return;
    }

    Serial.print(F("Temp: "));  Serial.print(temperature, 1); Serial.print(F("°C  "));
    Serial.print(F("Hum: "));   Serial.print(humidity, 1);    Serial.print(F("%  "));
    Serial.print(F("HeatIdx: ")); Serial.print(heatIndex, 1); Serial.println(F("°C"));
  }
}

#define TRIG_PIN 7
#define ECHO_PIN 8

void setup() {
  Serial.begin(115200);
  pinMode(TRIG_PIN, OUTPUT);
  pinMode(ECHO_PIN, INPUT);
}

float readDistanceCm() {
  // 1. Send 10µs trigger pulse
  digitalWrite(TRIG_PIN, LOW);
  delayMicroseconds(2);
  digitalWrite(TRIG_PIN, HIGH);
  delayMicroseconds(10);
  digitalWrite(TRIG_PIN, LOW);

  // 2. Measure echo pulse width in microseconds
  long duration = pulseIn(ECHO_PIN, HIGH, 25000); // 25ms timeout

  if (duration == 0) return -1;  // timeout = no echo

  // 3. Convert: sound travels 343 m/s = 0.0343 cm/µs
  //    divide by 2 for round trip
  return duration * 0.0343 / 2.0;
}

void loop() {
  float dist = readDistanceCm();
  if (dist < 0) {
    Serial.println(F("Out of range"));
  } else {
    Serial.print(F("Distance: "));
    Serial.print(dist, 1);
    Serial.println(F(" cm"));
  }
  delay(100);
}

#include <Servo.h>
// Servo library is built into Arduino IDE — no install needed

const int SERVO_PIN = 9;
const int POT_PIN   = A0;  // potentiometer to control servo
Servo myServo;

void setup() {
  myServo.attach(SERVO_PIN);  // must be a PWM pin
  Serial.begin(115200);
}

void loop() {
  // Read potentiometer (0–1023) and map to angle (0–180)
  int potValue = analogRead(POT_PIN);
  int angle    = map(potValue, 0, 1023, 0, 180);

  myServo.write(angle);

  Serial.print(F("Pot: ")); Serial.print(potValue);
  Serial.print(F("  Angle: ")); Serial.print(angle); Serial.println(F("°"));

  delay(15);  // give servo time to move
}

// L298N H-Bridge motor driver
// Connect: ENA=PWM pin 9, IN1=pin 7, IN2=pin 6
// Motor A between OUT1 and OUT2

#define ENA 9  // PWM for speed
#define IN1 7
#define IN2 6

void setup() {
  pinMode(ENA, OUTPUT);
  pinMode(IN1, OUTPUT);
  pinMode(IN2, OUTPUT);
}

void motorForward(int speed) {   // speed: 0-255
  digitalWrite(IN1, HIGH);
  digitalWrite(IN2, LOW);
  analogWrite(ENA, speed);
}

void motorBackward(int speed) {
  digitalWrite(IN1, LOW);
  digitalWrite(IN2, HIGH);
  analogWrite(ENA, speed);
}

void motorStop() {
  analogWrite(ENA, 0);
}

void loop() {
  motorForward(200);  delay(2000);   // forward 2s at ~78%
  motorStop();        delay(500);    // stop
  motorBackward(200); delay(2000);   // reverse 2s
  motorStop();        delay(1000);
}
